485	+import { spawn } from "node:child_process";
486	+import { existsSync } from "node:fs";
487	+import { renderSVG } from "uqr";
488	+import { z } from "zod";
489	+
490	+// Optional access from the owner's phone and tablet: `tailscale serve` forwards their private
491	+// Tailscale address to this Moneo, which keeps listening on 127.0.0.1 only. Tailscale remembers the
492	+// setting, so Moneo stores nothing and nothing here runs unless Settings asks.
493	+export type PhoneAccess =
494	+  | { state: "off" | "not_installed" | "busy" }
495	+  | { state: "signed_out" | "needs_approval"; link: string | null }
496	+  | { state: "on"; url: string; qr: string };
497	+
498	+const INSTALLED = ["C:\\Program Files\\Tailscale\\tailscale.exe", "/Applications/Tailscale.app/Contents/MacOS/Tailscale"];
499	+const LOGIN_LINK = /https:\/\/login\.tailscale\.com\/\S+/;
500	+const statusSchema = z.object({ BackendState: z.string(), AuthURL: z.string().optional(), Self: z.object({ DNSName: z.string() }).optional() });
501	+const serveSchema = z.object({
502	+  TCP: z.record(z.string(), z.unknown()).optional(),
503	+  Web: z.record(z.string(), z.object({ Handlers: z.record(z.string(), z.object({ Proxy: z.string().optional() })).optional() })).optional(),
504	+});
505	+type Result = { ok: boolean; output: string; missing?: boolean };
506	+
507	+const cli = () => INSTALLED.find(path => existsSync(path)) ?? "tailscale";
508	+const target = () => `http://127.0.0.1:${Number(process.env.PORT ?? 3000)}`;
509	+const linkIn = (output: string) => output.match(LOGIN_LINK)?.[0] ?? null;
510	+
511	+/** Runs the CLI. Commands waiting on the owner print a login link and never exit, so they stop there. */
512	+function run(args: string[]) {
513	+  return new Promise<Result>(resolve => {
514	+    let output = "";
515	+    const child = spawn(cli(), args, { windowsHide: true });
516	+    const timer = setTimeout(() => { child.kill(); resolve({ ok: false, output }); }, 15_000);
517	+    const done = (result: Result) => { clearTimeout(timer); resolve(result); };
518	+    const read = (chunk: Buffer) => {
519	+      output += chunk;
520	+      if (linkIn(output)) { child.kill(); done({ ok: false, output }); }
521	+    };
522	+    child.stdout.on("data", read);
523	+    child.stderr.on("data", read);
524	+    child.on("error", error => done({ ok: false, output, missing: (error as NodeJS.ErrnoException).code === "ENOENT" }));
525	+    child.on("close", code => done({ ok: code === 0, output }));
526	+  });
527	+}
528	+
529	+export async function phoneAccess(): Promise<PhoneAccess> {
530	+  const status = await run(["status", "--json"]);
531	+  if (status.missing) return { state: "not_installed" };
532	+  // No JSON means the Tailscale service is stopped; opening the app starts it.
533	+  if (!status.output.trim().startsWith("{")) return { state: "signed_out", link: null };
534	+  const tailscale = statusSchema.parse(JSON.parse(status.output));
535	+  const host = tailscale.Self?.DNSName.replace(/\.$/, "");
536	+  if (tailscale.BackendState !== "Running" || !host) return { state: "signed_out", link: tailscale.AuthURL || null };
537	+  const serve = serveSchema.parse(JSON.parse((await run(["serve", "status", "--json"])).output));
538	+  const proxy = serve.Web?.[`${host}:443`]?.Handlers?.["/"]?.Proxy;
539	+  if (proxy === target()) return { state: "on", url: `https://${host}`, qr: renderSVG(`https://${host}`) };
540	+  return { state: proxy || serve.TCP?.["443"] ? "busy" : "off" };
